// Lava lamp: slow rising blobs, glow, sparkle, motion-reactive wobble.
// Simulation lives in update() on a small fixed-point lattice buffer;
// shade() is a handful of fixed-point ops per LED.

uniform float speed : 0.0 .. 5.0 = 1.0;      // blob rise rate
uniform float glow : 0.0 .. 2.0 = 1.0;       // master brightness
uniform float palette : 0.0 .. 1.0 = 0.0;    // hue sweep of the wax
uniform bool motion : 0.0 .. 1.0 = 0.0;      // tilt/wobble the lamp
uniform vec3 tint : color = 1.0, 0.45, 0.12; // wax colour

state fixed heat[32];       // 1D lattice: heat field, wraps vertically
state fixed ph;             // slow phase (turns)
state float wob;            // wobble phase
state float lvl;            // liquid level from tilt
state bool inited;

void update() {
  if (!inited) {
    for (int i = 0; i < 32; i = i + 1) {
      heat[i] = fixed(hash(float(i) * 0.371));
    }
    inited = true;
  }

  // integrate phases
  ph = fract(ph + fixed(dt * speed * 0.05));
  wob = fract(wob + dt * 0.4);

  // liquid level from tilt (motion reactive): -0.5..0.5
  lvl = motion > 0.5 ? imu_gravity.y * 0.5 : 0.0;

  // diffuse + rise: heat[i] = mix(heat[i-1], heat[i+1], 0.5) with upward bias
  fixed h0 = heat[0];
  for (int i = 0; i < 32; i = i + 1) {
    int lo = (i + 31) & 31;
    int hi = (i + 1) & 31;
    fixed avg = (heat[lo] + heat[hi]) * fixed(0.5);
    fixed up = heat[hi] * fixed(0.75) + heat[lo] * fixed(0.25);
    heat[i] = avg * fixed(0.5) + up * fixed(0.5);
  }
  heat[0] = heat[0] + h0 * fixed(0.0); // keep lattice alive
}

vec3 shade(Led led) {
  fixed y = fixed(led.pos.y) * fixed(3.3333);   // 0..1 over 0.30 m
  fixed level = y + fixed(lvl);
  fixed idx = level * fixed(32.0);
  int i0 = int(idx) & 31;
  int i1 = (i0 + 1) & 31;
  fixed f = fract(idx);
  fixed h = mix(heat[i0], heat[i1], float(f));

  // blob threshold + soft edge
  fixed on = clamp((h - fixed(0.45)) * fixed(6.0), fixed(0.0), fixed(1.0));
  on = on * on * (fixed(3.0) - on * fixed(2.0)); // smoothstep-ish

  // hue: wax palette + slow sweep + per-blob variation
  fixed hue = fract(fixed(palette) + ph + h * fixed(0.15));
  vec3 wax = hsv2rgb(hue, fixed(0.85), fixed(1.0));

  // dark glass when off, hot wax when on
  vec3 col = mix(vec3(0.02, 0.01, 0.01), wax * tint, float(on));

  // sparkle at blob edges
  fixed sp = clamp((h - fixed(0.42)) * fixed(30.0), fixed(0.0), fixed(1.0))
           - clamp((h - fixed(0.50)) * fixed(30.0), fixed(0.0), fixed(1.0));
  col = col + vec3(float(sp)) * fixed(0.15) * float(on);

  // wobble: horizontal sway with height
  fixed wobamt = fixed(motion) * sin(fixed(wob) * fixed(6.2832)) * fixed(0.02);
  col = col + vec3(wobamt * float(led.pos.x));

  return col * glow;
}

